{"path":"outputs/t07_query.sparql","content":"PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX p: <http://www.wikidata.org/prop/>
PREFIX ps: <http://www.wikidata.org/prop/statement/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?item ?itemLabel ?coords
WHERE {
  # Get items located in Alicante (Q11959) or its subdivisions
  ?item wdt:P131* wd:Q11959 .

  # Filter for cultural POI types using UNION
  {
    # Museum
    ?item wdt:P31 wd:Q33506 .
  }
  UNION
  {
    # Art gallery
    ?item wdt:P31 wd:Q33936 .
  }
  UNION
  {
    # Library
    ?item wdt:P31 wd:Q36632 .
  }
  UNION
  {
    # Monument
    ?item wdt:P31 wd:Q49846 .
  }
  UNION
  {
    # Theatre building
    ?item wdt:P31 wd:Q56873 .
  }

  # Get coordinates (P625)
  ?item p:P625 ?coordStatement .
  ?coordStatement ps:P625 ?coords .

  # Get item label
  SERVICE wikibase:label {
    bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en".
  }
}
LIMIT 100
"}

